INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65680301', 65680301, 'analyze_legacy', 'Kota Surakarta', 'kabkota', 'PUSKESMAS JAYENGAN', 'PMT Pangan Diet Khusus (PDK)', 'Barang', 'E-Purchasing', 'Jawa Tengah, Surakarta (Kota)', 2450000, 'January 2026', 'APBD', 1, 1, '5 Balita x 14 Hari', 'PMT Pangan Diet Khusus (PDK);', 'Pangan Diit Khusus (PDK) adalah makanan yang disiapkan secara khusus untuk bayi, balita, atau individu dengan kondisi kesehatan tertentu yang membutuhkan pengaturan jenis, jumlah, dan cara pengolahan makanan sesuai kebutuhan gizinya. PDK diberikan sebagai bagian dari tata laksana gizi untuk membantu pemulihan atau pengendalian kondisi kesehatan, seperti gangguan gizi, penyakit tertentu, atau kondisi medis khusus, dan disusun berdasarkan pedoman gizi serta anjuran tenaga kesehatan. Paket pekerjaan pangan diit khusus diberikan kepada 5 orang bayi dan balita sesuai pedoman Pemberian Diit Khusus (PDK) dalam tata laksana gizi. Pangan diit disesuaikan dengan kondisi kesehatan, usia, dan kebutuhan gizi sasaran. Pemberian dilakukan setiap hari selama 14 hari berturut-turut. Makanan disiapkan secara higienis, aman, dan sesuai standar porsi serta jenis pangan yang dianjurkan. Pelaksanaan dan kepatuhan konsumsi dipantau oleh petugas kesehatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2285285);
