INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65679032', 65679032, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Jasa Distribusi Obat, Vaksin dan Perbekalan Kesehatan Tahun 2026', 'Jasa Lainnya', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 19527625000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 PT', 'Belanja Jasa Lainnya dengan Mendistribusikan Obat, Vaksin dan Perbekalan Kesehatan Tahun 2026', 'Spesifikasi distribusi obat, vaksin dan perbekalan kesehatan sebagai berikut : 1. Melampirkan surat pernyataan: a. Mampu mendistribusikan perbekalan kesehatan ke 38 provinsi dan seluruh kab/kota dibuktikan dengan surat pernyataan. b. Mampu menyediakan minimal 1 orang supervisor sebagai PIC dan tenaga administrasi dengan pendidikan minimal SMA, dibuktikan dengan surat keterangan yang menyatakan bahwa yang bersangkutan merupakan pegawai tetap. c. Mampu menyediakan minimal 1 tenaga kefarmasian dengan pendidikan minimal D3 Farmasi dibuktikan dengan STR aktif. d. Mampu menyediakan armada tambahan (blindvan/engkel box/HDL box/Wingsbox) dan armada untuk pengangkutan dan penanganan dalam kondisi suhu khusus (2-8 0C) 2. Menyediakan gudang transit milik sendiri/sewa minimal 1.000 m2 di daerah Jakarta/Bogor/Depok/Tangerang/Bekasi dan sarana pendukung dalam penyimpanan seperti Pallet, hand pallet, dan chiller suhu 2-8 0C, serta sarana pendukung dalam keamanan seperti APAR, pest control, CCTV dan alarm. 3. Menyediakan armada minimal blindvan 1 unit, engkel box 1 unit, HDL box 1 unit, Wingsbox 1 unit milik sendiri/sewa. 4. Menyediakan tenaga operasional minimal 10 orang dalam proses handling obat dan perbekalan kesehatan. 5. Menyediakan sarana penunjang dalam repacking untuk pendistribusian obat dan perbekalan kesehatan dengan kondisi tertentu seperti karung, peti kayu, bubble wrap, steoroform, dan Coldpack dibuktikan dengan surat pernyataan 6. Menyediakan sistem/aplikasi/perangkat lunak dalam memantau proses pendistribusian obat dan perbekalan kesehatan ke daerah/lokasi tujuan yang dapat diakses oleh petugas IFP (dengan melampirkan bukti screenshoot dashboard aplikasi/sistem) 7. Menyediakan armada minimal blindvan 1 unit, engkel box 1 unit, HDL box 1 unit, Wingsbox 1 unit milik sendiri/sewa. 8. Bersedia melakukan validasi proses pengiriman untuk produk rantai dingin (untuk memastikan suhu pengiriman tidak menyimpang dari yang dipersyaratkan) dibuktikan dengan surat pernyataan 9. Bersedia dilakukan verifikasi lapangan pada saat evaluasi Kualifikasi Penyedia Berpengalaman dalam pendistribusian', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2285492);
