INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65681298', 65681298, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'Digitasi Jaringan Kabel Udara di Kota Tangerang', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 96705500, 'February 2026', 'APBD', 1, 1, '1', '"a. Melaksanakan koordinasi dan persiapan teknis dengan Dinas Pekerjaan Umum dan Penataan Ruang Kota Tangerang serta instansi terkait lainnya. b. Mengumpulkan dan mengkaji data sekunder, termasuk data perizinan jaringan kabel udara dari Bidang Tata Ruang DPUPR Kota Tangerang dan sumber lain yang relevan. c. Melakukan inventarisasi awal jaringan kabel udara eksisting berdasarkan data perizinan dan data pendukung. d. Melaksanakan survei lapangan untuk mengidentifikasi, memverifikasi, dan mendokumentasikan jaringan kabel udara eksisting. e. Melakukan pengukuran posisi jaringan kabel udara menggunakan perangkat GNSS/GPS sesuai standar teknis. f. Melakukan digitasi jaringan kabel udara ke dalam sistem informasi geografis (SIG) sesuai standar yang ditetapkan. g. Menyusun basis data spasial jaringan kabel udara beserta atribut dan metadata pendukung. h. Melakukan validasi dan verifikasi hasil digitasi bersama tim teknis dan/atau Pejabat Pembuat Komitmen. i. Menyusun peta tematik jaringan kabel udara sebagai bahan perencanaan penertiban dan penataan. j. Menyusun laporan pendahuluan, laporan antara, dan laporan akhir pelaksanaan pekerjaan. k. Menyerahkan seluruh hasil pekerjaan dalam bentuk data digital dan dokumen sesuai ketentuan yang berlaku. Data Base dengan menggunakan program GIS.', '1 Orang Team Leader Teknik Sipil/ Teknik Geodesi/ Teknik Geoteknik Ahli Muda S1 Pengalaman 2 Tahun 3 Orang Tenaga Pendukung Surveyor 1 Orang Tenaga Pendukung Operator SIG 1 Orang Tenaga Pendukung Operator Komputer', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2286158);
